import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def count_good_partitions(sequence):
    n = len(sequence)
    count = 0

    # Partitions are for 1 <= k < n
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        L_k = list_lcm(A_k)
        G_k_plus_1 = list_gcd(B_k)

        if L_k == G_k_plus_1:
            count += 1
            # print(f"k={k}: Good partition found. L_k={L_k}, G_{k+1}={G_k_plus_1}")
    return count

